// Official Merchant Payment Configuration
// Embedded QR Code & UPI Clearance

export const DEFAULT_PAYMENT_QR = '/payment-qr.jpg';
export const DEFAULT_UPI_ID = '8074282728@ptaxis';
export const DEFAULT_PAYEE_NAME = 'Manepalli Mounish Sai Gandhi';
export const DEFAULT_UPI_URI = 'upi://pay?pa=8074282728@ptaxis&pn=Manepalli%20Mounish%20Sai%20Gandhi';

// Base64 Data URL for zero-dependency offline rendering
export const DEFAULT_QR_BASE64 = 'data:image/jpeg;base64,';

export const getPaymentQR = () => {
  return localStorage.getItem('platformQRUrl') || DEFAULT_QR_BASE64;
};

export const getPaymentUPI = () => {
  return localStorage.getItem('platformUPIId') || DEFAULT_UPI_ID;
};
